#!/usr/bin/env node
/**
 * Build timings.js from data/timings.csv.
 *
 *   node scripts/build-timings.mjs
 *
 * The CSV is the human-editable source: one row per verse per round, with
 * `start_seconds` the only field you normally change. The generated file is
 * loaded before script.js and, when present, replaces proportional line timing
 * for the rounds it contains. Rounds without a complete 15-verse set fall back
 * to the weighted model. Sync Lab calibration takes precedence over both.
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const csvPath = path.join(root, "data", "timings.csv");
const outPath = path.join(root, "timings.js");
const script = fs.readFileSync(path.join(root, "script.js"), "utf8");
const nominal = Number((script.match(/NOMINAL_DURATION\s*=\s*(\d+)/) || [])[1] || 5837);

function parseCsv(text) {
  const rows = [];
  let row = [];
  let field = "";
  let quoted = false;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (quoted) {
      if (ch === '"' && text[i + 1] === '"') { field += '"'; i++; }
      else if (ch === '"') quoted = false;
      else field += ch;
    } else if (ch === '"') quoted = true;
    else if (ch === ",") { row.push(field); field = ""; }
    else if (ch === "\n") { row.push(field); rows.push(row); row = []; field = ""; }
    else if (ch !== "\r") field += ch;
  }
  if (field.length || row.length) { row.push(field); rows.push(row); }
  return rows;
}

if (!fs.existsSync(csvPath)) {
  console.error("Missing data/timings.csv");
  process.exit(1);
}

const rows = parseCsv(fs.readFileSync(csvPath, "utf8"));
const header = rows.shift();
const required = ["round", "verse", "start_seconds"];
const missing = required.filter((key) => !header.includes(key));
if (missing.length) {
  console.error("CSV is missing columns: " + missing.join(", "));
  process.exit(1);
}
const index = Object.fromEntries(header.map((name, i) => [name, i]));

const rounds = new Map();
const problems = [];
rows.forEach((cells, lineNumber) => {
  if (!cells.some((cell) => cell.trim() !== "")) return;
  const round = Number(cells[index.round]);
  const verse = Number(cells[index.verse]);
  const start = Number(cells[index.start_seconds]);
  if (!Number.isInteger(round) || round < 1 || round > 9) {
    problems.push(`row ${lineNumber + 2}: round must be 1–9`);
    return;
  }
  if (!Number.isInteger(verse) || verse < 1 || verse > 15) {
    problems.push(`row ${lineNumber + 2}: verse must be 1–15`);
    return;
  }
  if (!Number.isFinite(start) || start < 0 || start > nominal) {
    problems.push(`row ${lineNumber + 2}: start_seconds must be 0–${nominal}`);
    return;
  }
  if (!rounds.has(round)) rounds.set(round, new Map());
  const set = rounds.get(round);
  if (set.has(verse)) {
    problems.push(`row ${lineNumber + 2}: duplicate round ${round} verse ${verse}`);
    return;
  }
  set.set(verse, start);
});

if (problems.length) {
  problems.forEach((problem) => console.error("FAIL " + problem));
  console.error(`\n${problems.length} problem(s); timings.js not written.`);
  process.exit(1);
}

const output = {};
let lastStart = -1;
let totalLines = 0;
for (let round = 1; round <= 9; round++) {
  if (!rounds.has(round)) continue;
  const set = rounds.get(round);
  if (set.size !== 15) {
    console.error(`Round ${round} has ${set.size} rows; need exactly 15. Refusing a partial round.`);
    process.exit(1);
  }
  const starts = [];
  for (let verse = 1; verse <= 15; verse++) {
    const start = set.get(verse);
    if (start <= lastStart) {
      console.error(`Round ${round} verse ${verse} starts at ${start}, not after the previous line (${lastStart}).`);
      process.exit(1);
    }
    starts.push(Math.round(start * 10) / 10);
    lastStart = start;
  }
  output[round] = starts;
  totalLines += starts.length;
}

const banner = `/* Generated by scripts/build-timings.mjs from data/timings.csv.\n   Edit the CSV, then run: node scripts/build-timings.mjs\n   Do not edit this file by hand. */\n`;
const payload = {
  version: 1,
  generatedAt: new Date().toISOString().slice(0, 10),
  source: "data/timings.csv",
  nominalDuration: nominal,
  rounds: output
};
fs.writeFileSync(outPath, banner + "window.SUAT_TIMINGS = " + JSON.stringify(payload, null, 2) + ";\n");

const roundNumbers = Object.keys(output);
console.log(`WROTE timings.js — ${totalLines} cues across ${roundNumbers.length} round(s)`);
console.log(`Rounds: ${roundNumbers.join(", ")} · nominal duration ${nominal}s`);
